import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';import { IStoryTranslation, TRANSLATION_STATUS_CONSTANTS, TRANSLATION_TYPE } from '@core/services/api/model/story-translation';import { UserLanguageService } from '@core/services/locales/user-language.service';import { TranslateService } from '@ngx-translate/core';import { Observable } from 'rxjs';import { switchMap } from 'rxjs/operators';@Component({  selector: 'app-story-translations',  templateUrl: './story-translations.component.html',  styleUrls: ['./story-translations.component.scss'],  changeDetection: ChangeDetectionStrategy.OnPush,})export class StoryTranslationsComponent {  @Input() originalLanguage: string;  @Input() translations: IStoryTranslation[];  @Input() selectedLanguage: string;  @Input() currentTranslationType: TRANSLATION_TYPE;  @Output() languageSelected = new EventEmitter<IStoryTranslation>();  translationSelectOpen = false;  readonly translationTypes = TRANSLATION_TYPE;  get allTranslations(): IStoryTranslation[] {    return this.translations;  }  get selectedTranslationType(): TRANSLATION_TYPE {    const translationType = this.allTranslations.find((translation) => translation.code === this.selectedLanguage)?.type;    return translationType;  }  get changeLanguageButtonText(): Observable<string> {    const selectedLanguageCode = this.getLanguageCode(this.selectedLanguage);    return this.translateService.get(selectedLanguageCode).pipe(      switchMap((language) => {        if (this.selectedLanguage === this.originalLanguage) {          return this.translateService.get('story.changeTranslation');        }        return this.translateService.get(`story.translatedTo`, { language });      }),    );  }  get storyLanguage(): Observable<string> {    return this.translateService.get(`languages.${this.originalLanguage}`);  }  get isOriginalSameAsCurrent(): boolean {    return this.selectedLanguage === this.originalLanguage;  }  constructor(private translateService: TranslateService, private userLangService: UserLanguageService, private cd: ChangeDetectorRef) {}  getLanguageCode(code: string): string {    return `languages.${code}`;  }  handleLanguageClick(translation: IStoryTranslation): void {    this.languageSelected.emit(translation);    this.translationSelectOpen = false;    this.cd.markForCheck();  }  isTranslationNotAvailable(status: TRANSLATION_STATUS_CONSTANTS): boolean {    return status !== TRANSLATION_STATUS_CONSTANTS.TRANSLATED;  }  toggleTranslationSelect(): void {    this.translationSelectOpen = !this.translationSelectOpen;    this.cd.detectChanges();  }}